package com.sami.app.purchasing.web; import com.sami.app.common.api.ApiResponse; import com.sami.app.purchasing.service.SupplierInvoiceService; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/supplier-invoices") @RequiredArgsConstructor public class SupplierInvoiceController{private final SupplierInvoiceService service;@GetMapping("/{id}") @PreAuthorize("@authz.has('purchasing:view')") public ApiResponse<Map<String,Object>> get(@PathVariable Long id){return ApiResponse.ok(service.get(id));}@PostMapping @PreAuthorize("@authz.has('purchasing:create')") public ApiResponse<Map<String,Object>> create(@RequestParam Long companyId,@RequestParam Long branchId,@RequestParam Long purchaseOrderId,@RequestParam Long goodsReceiptId,@RequestBody Map<String,Object> body){return ApiResponse.ok(service.create(companyId,branchId,purchaseOrderId,goodsReceiptId,(List<Map<String,Object>>)body.get("lines"),(String)body.get("notes")));}}
